from taf.sbts.oam.sc.rest.schemas.base import SchemaField, SchemaObject


class SiteInfoSMV1(SchemaObject):
    operational_state = SchemaField(name="operational_state", not_null=True)
    blocking_state = SchemaField(name="blocking_state", not_null=False)

    def __init__(self, operational_state=None, blocking_state=None):
        self.operational_state = operational_state
        self.blocking_state = blocking_state

        super(SiteInfoSMV1, self).__init__()
